import type { Bucket, Provider } from './report-contracts.ts';
import { compactCount as compact } from './reporting-chart-utils.ts';
import {
  deliveryOf,
  isUncovered,
  providersIn,
  providerTokens,
  railOf,
} from './reporting-chart-model.ts';

// The aligned chart's geometry as a pure function (ported from ui.js `alignedChart` and `niceMax`; every constant below is the
// prototype's). The component draws what this returns, so the picture can be checked without a browser. Nothing here touches
// the DOM, and no text is built from user data: React escapes it where it is drawn.
//
// Two panels share one x-axis and each has its own y-axis and unit (no shared numeric axis): merged PRs as a count, and
// recorded local tokens, stacked by provider. A thin coverage rail sits under them. The shapes say what the data does and does
// not say:
//   delivery  bar for a count, a flat tick for a covered zero, nothing for none, future or a count the API did not give;
//   usage     a segment per provider with tokens, a flat tick for a covered zero, hatching where there is no coverage,
//             nothing for a bucket that has not happened yet. A null is never drawn as a zero;
//   rail      solid for complete, hatched for partial, an empty outline for none.
// Provider tokens are separate segments. They are stacked to share a bar, and the stack is never labelled with a total.

/** The prototype's constants. */
export const GEOMETRY = {
  /** 240, not larger: at a 320px window the chart sits in a 256px card body, and a larger minimum would spill out of it. */
  minWidth: 240,
  /** Below this width the chart is drawn tighter: a narrower label column and shorter panels. */
  compactBelow: 480,
  padLeftWide: 52,
  padLeftCompact: 40,
  padRight: 6,
  top: 26,
  panelGap: 44,
  deliveryHeightWide: 92,
  deliveryHeightCompact: 72,
  usageHeightWide: 132,
  usageHeightCompact: 104,
  railGap: 8,
  railHeight: 6,
  maxBarWidth: 28,
  /** Where the width is not known yet (a first render before anything is measured). */
  fallbackWidth: 720,
  /** The notes drawn inside a panel are 20px tall; their width is an estimate of the text at 11px plus padding. */
  noteHeight: 20,
  noteCharWidth: 5.9,
  notePadding: 16,
  /** An x label needs about this much room, so labels are thinned to fit. */
  labelRoom: 64,
} as const;

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** The axis maximum for a value: 1, 2, 5 or 10 times a power of ten, so the gridlines fall on round numbers. */
export function niceMax(value: number): number {
  if (!(value > 0)) return 1;
  const exponent = 10 ** Math.floor(Math.log10(value));
  const mantissa = value / exponent;
  return (mantissa <= 1 ? 1 : mantissa <= 2 ? 2 : mantissa <= 5 ? 5 : 10) * exponent;
}

const round = (n: number): number => Math.round(n * 100) / 100;
const rect = (x: number, y: number, width: number, height: number): Rect => ({
  x: round(x),
  y: round(y),
  width: round(width),
  height: round(height),
});

export interface AxisTick {
  value: number;
  /** The gridline's y. */
  y: number;
  /** The label, or null where the prototype leaves the tick unlabelled (the middle of an odd count axis). */
  label: string | null;
  /** The baseline is drawn solid; the other gridlines are dashed. */
  baseline: boolean;
}

export interface PanelLayout {
  top: number;
  height: number;
  /** The y of the panel's title row. */
  titleY: number;
  /** The axis maximum, a niceMax value. */
  max: number;
  /** Top, middle and base, in that order. */
  ticks: AxisTick[];
}

export type DeliveryShape =
  { kind: 'bar'; rect: Rect; radius: number } | { kind: 'zero'; rect: Rect } | { kind: 'empty' };

export interface UsageSegment {
  provider: Provider;
  rect: Rect;
  /** The provider's own token count, for tests and tooltips. Never added to another provider's. */
  value: number;
}

export type UsageShape =
  | { kind: 'unavailable'; rect: Rect }
  | { kind: 'stack'; segments: UsageSegment[] }
  | { kind: 'zero'; rect: Rect }
  | { kind: 'empty' };

export type RailShape = { kind: 'complete' | 'partial' | 'none'; rect: Rect } | { kind: 'empty' };

export interface BucketShape {
  index: number;
  /** The whole column, both panels and the rail: what is highlighted when selected, and where the pointer lands. */
  band: Rect;
  delivery: DeliveryShape;
  usage: UsageShape;
  rail: RailShape;
}

export interface ChartNote {
  kind: 'unavailable' | 'no-delivery';
  text: string;
  /** The background box. */
  box: Rect;
  /** Where the centred text sits. */
  x: number;
  y: number;
}

export interface XLabel {
  index: number;
  x: number;
  y: number;
  text: string;
  /** Greyed: the bucket has not happened yet. */
  upcoming: boolean;
}

/** The one caption over a run of upcoming buckets: centred across the run, in the usage panel. */
export interface UpcomingNote {
  text: string;
  x: number;
  y: number;
}

export interface ChartLayout {
  width: number;
  height: number;
  providers: Provider[];
  /** The plot spans `padLeft` to `width - padRight`. */
  padLeft: number;
  padRight: number;
  plotWidth: number;
  /** The width of one bucket's column. */
  band: number;
  barWidth: number;
  delivery: PanelLayout;
  usage: PanelLayout;
  /** The coverage rail's top and height, and the baseline of the x labels. */
  railY: number;
  railHeight: number;
  labelY: number;
  buckets: BucketShape[];
  notes: ChartNote[];
  xLabels: XLabel[];
  /** Said once across the longest run of upcoming buckets when the run is wide enough to hold it, or null. */
  upcomingNote: UpcomingNote | null;
}

export interface LayoutOptions {
  /** The providers to draw, in stacking order (the first is at the bottom). Default: the ones the buckets carry. */
  providers?: readonly Provider[];
  /** Said inside a long run of unavailable history ("History unavailable before Mar 14, 2026"). */
  unavailableText?: string;
  /** Said inside the delivery panel when no repo is tracked. Omitted, the panel says nothing. */
  noDeliveryText?: string;
  /** Said once across a run of upcoming buckets ("Upcoming"). Omitted, the run is left silent. */
  upcomingText?: string;
}

const estimatedTextWidth = (text: string): number =>
  text.length * GEOMETRY.noteCharWidth + GEOMETRY.notePadding;

/** Where everything goes for these buckets at this pixel width (never narrower than 240). */
export function layoutAlignedChart(
  buckets: readonly Bucket[],
  width: number,
  options: LayoutOptions = {},
): ChartLayout {
  const g = GEOMETRY;
  const providers = [...(options.providers ?? providersIn(buckets))];
  const n = buckets.length;
  const W = Math.max(g.minWidth, Math.round(width || g.fallbackWidth));
  const narrow = W < g.compactBelow;
  const padLeft = narrow ? g.padLeftCompact : g.padLeftWide;
  const plotWidth = W - padLeft - g.padRight;
  const aTop = g.top;
  const aH = narrow ? g.deliveryHeightCompact : g.deliveryHeightWide;
  const bTop = aTop + aH + g.panelGap;
  const bH = narrow ? g.usageHeightCompact : g.usageHeightWide;
  const railY = bTop + bH + g.railGap;
  const labelY = railY + g.railHeight + 16;
  const H = labelY + 6;
  const band = plotWidth / Math.max(n, 1);
  const barWidth = Math.max(1, Math.min(band * 0.68, g.maxBarWidth));

  // What each bucket says, read once.
  const deliveries = buckets.map(deliveryOf);
  const rails = buckets.map((bucket) => railOf(bucket, providers));

  // The axes. Only what is drawn sets the scale: a count that is not a number, or a usage bucket that is hatched or upcoming,
  // does not stretch it. The usage maximum is the tallest stack; it is a scale, and no total is ever written anywhere.
  let maxPrs = 1;
  let maxStack = 1;
  buckets.forEach((bucket, i) => {
    const delivery = deliveries[i]!;
    if ((delivery.kind === 'ok' || delivery.kind === 'syncing') && (delivery.prs ?? 0) > maxPrs) {
      maxPrs = delivery.prs ?? 0;
    }
    const rail = rails[i]!;
    if (rail === 'future' || isUncovered(rail)) return;
    let stack = 0;
    for (const provider of providers) stack += providerTokens(bucket, provider) ?? 0;
    if (stack > maxStack) maxStack = stack;
  });
  maxPrs = niceMax(maxPrs);
  maxStack = niceMax(maxStack);

  const panel = (
    top: number,
    height: number,
    max: number,
    format: (value: number) => string,
    labelMiddle: boolean,
    titleY: number,
  ): PanelLayout => ({
    top,
    height,
    titleY,
    max,
    ticks: [
      { value: max, y: top, label: format(max), baseline: false },
      {
        value: max / 2,
        y: top + height / 2,
        label: labelMiddle ? format(max / 2) : null,
        baseline: false,
      },
      { value: 0, y: top + height, label: '0', baseline: true },
    ],
  });

  const shapes = buckets.map((_, i): BucketShape => {
    const x0 = padLeft + i * band;
    const barX = x0 + (band - barWidth) / 2;
    const delivery = deliveries[i]!;
    const rail = rails[i]!;
    const bucket = buckets[i]!;

    const bandRect = rect(x0, aTop - 6, band, railY + g.railHeight - aTop + 6);

    // Delivery panel.
    let deliveryShape: DeliveryShape = { kind: 'empty' };
    const prs = delivery.kind === 'ok' || delivery.kind === 'syncing' ? delivery.prs : null;
    if (prs !== null && prs > 0) {
      const h = (prs / maxPrs) * aH;
      deliveryShape = {
        kind: 'bar',
        rect: rect(barX, aTop + aH - h, barWidth, h),
        radius: barWidth >= 6 ? 3 : 1,
      };
    } else if (delivery.kind === 'ok' && prs === 0) {
      // A covered zero. While the first backfill is still running a 0 is not yet known, so it gets no tick.
      deliveryShape = { kind: 'zero', rect: rect(barX, aTop + aH - 1.5, barWidth, 1.5) };
    }

    // Usage panel and rail.
    let usageShape: UsageShape = { kind: 'empty' };
    let railShape: RailShape = { kind: 'empty' };
    const railRect = rect(x0 + 0.5, railY, Math.max(band - 1, 0.5), g.railHeight);
    if (rail === 'future') {
      // Quiet: not a zero, not hatching.
    } else if (isUncovered(rail)) {
      usageShape = { kind: 'unavailable', rect: rect(x0, bTop, band, bH) };
      railShape = { kind: 'none', rect: railRect };
    } else {
      let y = bTop + bH;
      const segments: UsageSegment[] = [];
      let anyNumber = false;
      let total = 0;
      for (const provider of providers) {
        const value = providerTokens(bucket, provider);
        if (value === null) continue; // no number: no segment, and no zero either
        anyNumber = true;
        total += value;
        if (value > 0) {
          const h = (value / maxStack) * bH;
          y -= h;
          segments.push({ provider, rect: rect(barX, y, barWidth, h), value });
        }
      }
      if (segments.length > 0) usageShape = { kind: 'stack', segments };
      else if (anyNumber && total === 0) {
        usageShape = { kind: 'zero', rect: rect(barX, bTop + bH - 1.5, barWidth, 1.5) };
      }
      railShape = { kind: rail === 'ok' ? 'complete' : 'partial', rect: railRect };
    }

    return {
      index: i,
      band: bandRect,
      delivery: deliveryShape,
      usage: usageShape,
      rail: railShape,
    };
  });

  // Words inside the panels. A run of unavailable history is labelled once, when the run is wide enough to hold the words.
  const notes: ChartNote[] = [];
  const unavailableText = options.unavailableText;
  if (unavailableText) {
    const noteWidth = estimatedTextWidth(unavailableText);
    let runStart = -1;
    for (let i = 0; i <= n; i += 1) {
      const inRun = i < n && isUncovered(rails[i]!);
      if (inRun && runStart < 0) runStart = i;
      if (!inRun && runStart >= 0) {
        const runWidth = (i - runStart) * band;
        if (runWidth >= noteWidth + 8) {
          const cx = padLeft + runStart * band + runWidth / 2;
          const cy = bTop + bH / 2;
          notes.push({
            kind: 'unavailable',
            text: unavailableText,
            box: rect(cx - noteWidth / 2, cy - 11, noteWidth, g.noteHeight),
            x: round(cx),
            y: round(cy + 3),
          });
        }
        runStart = -1;
      }
    }
  }
  if (options.noDeliveryText) {
    const noteWidth = estimatedTextWidth(options.noDeliveryText);
    const cx = padLeft + plotWidth / 2;
    const cy = aTop + aH / 2;
    notes.push({
      kind: 'no-delivery',
      text: options.noDeliveryText,
      box: rect(cx - noteWidth / 2, cy - 11, noteWidth, g.noteHeight),
      x: round(cx),
      y: round(cy + 3),
    });
  }

  // One caption across the longest run of upcoming buckets, so the quiet area reads as "not yet" and not as a gap. Like the
  // unavailable note, it is only said where the run is wide enough to hold it; a narrow run stays silent rather than spill
  // over real bars.
  let upcomingNote: UpcomingNote | null = null;
  if (options.upcomingText) {
    let best = { start: -1, length: 0 };
    let runStart = -1;
    for (let i = 0; i <= n; i += 1) {
      const upcoming = i < n && rails[i] === 'future' && buckets[i]!.delivery === 'future';
      if (upcoming && runStart < 0) runStart = i;
      if (!upcoming && runStart >= 0) {
        if (i - runStart > best.length) best = { start: runStart, length: i - runStart };
        runStart = -1;
      }
    }
    if (best.start >= 0 && best.length * band >= estimatedTextWidth(options.upcomingText) + 8) {
      upcomingNote = {
        text: options.upcomingText,
        x: round(padLeft + best.start * band + (best.length * band) / 2),
        y: round(bTop + bH / 2 + 3),
      };
    }
  }

  // Axis labels, thinned so they never touch: one per 64px at most, and always the first.
  const maxLabels = Math.max(3, Math.floor(plotWidth / g.labelRoom));
  const step = Math.max(1, Math.ceil(n / maxLabels));
  const xLabels: XLabel[] = [];
  for (let i = 0; i < n; i += step) {
    const bucket = buckets[i]!;
    xLabels.push({
      index: i,
      x: round(padLeft + i * band + band / 2),
      y: labelY,
      text: bucket.short,
      upcoming: bucket.delivery === 'future' && rails[i] === 'future',
    });
  }

  return {
    width: W,
    height: H,
    providers,
    padLeft,
    padRight: g.padRight,
    plotWidth: round(plotWidth),
    band: round(band),
    barWidth: round(barWidth),
    delivery: panel(aTop, aH, maxPrs, String, maxPrs % 2 === 0, 12),
    usage: panel(bTop, bH, maxStack, compact, true, bTop - 14),
    railY,
    railHeight: g.railHeight,
    labelY,
    buckets: shapes,
    notes,
    xLabels,
    upcomingNote,
  };
}
